import Testing

extension Tag {
    /// A vocabulary declared with the DSL, as its published document defines it.
    @Tag static var vocabulary: Self
    /// Types generated by the `@Ontology` macro.
    @Tag static var generated: Self
    /// Properties, their domains, ranges and characteristics.
    @Tag static var property: Self
    /// Values read where a term leaves the runtime (serialization, translation).
    @Tag static var boundary: Self
    /// A WebID profile built from the generated types.
    @Tag static var webID: Self
}
